// Generates lib/src/core/constants.g.dart (Dart enums) from BrainFlow's
// brainflow_constants.h. Run: dart run tool/generate_constants.dart
//
// The header uses C++ `enum class`, which ffigen (C mode) cannot parse, and
// we want idiomatic Dart enums anyway: SYNTHETIC_BOARD -> syntheticBoard,
// each carrying BrainFlow's integer `value`.
import 'dart:io';

final _root = Platform.script.resolve('../');

void main() {
  final header = File.fromUri(
    _root.resolve('third_party/brainflow/include/brainflow_constants.h'),
  ).readAsStringSync();

  final out = StringBuffer('''
// Generated by tool/generate_constants.dart from brainflow_constants.h.
// Do not edit by hand.

/// Common interface of all BrainFlow integer enums.
abstract interface class BrainFlowEnum {
  /// The integer BrainFlow uses for this value in its C API.
  int get value;
}
''');

  final enumRe = RegExp(r'enum class (\w+) : int\s*\{([^}]*)\};');
  final entryRe = RegExp(r'^\s*(\w+)\s*=\s*(-?\d+)\s*,?\s*(?://\s*(.*))?$');
  for (final match in enumRe.allMatches(header)) {
    final name = match[1]!;
    final entries = [
      for (final line in match[2]!.split('\n'))
        if (entryRe.firstMatch(line) case final m?) (m[1]!, m[2]!, m[3]),
    ];
    out
      ..writeln()
      ..writeln('/// BrainFlow `$name`.')
      ..writeln('enum $name implements BrainFlowEnum {');
    for (final (cName, value, comment) in entries) {
      final doc = (comment == null || comment.trim().isEmpty)
          ? '`$cName`'
          : '`$cName`: ${comment.trim()}';
      out
        ..writeln('  /// $doc')
        ..writeln('  ${_camel(cName)}($value),');
    }
    out.write('''
  ;

  const $name(this.value);

  @override
  final int value;

  static final _byValue = {for (final e in values) e.value: e};

  /// Returns the member with BrainFlow integer [value].
  ///
  /// Throws [ArgumentError] if there is none.
  static $name fromValue(int value) =>
      _byValue[value] ?? (throw ArgumentError.value(value, 'value', 'Unknown $name'));
}
''');
  }

  final file = File.fromUri(_root.resolve('lib/src/core/constants.g.dart'))
    ..writeAsStringSync(out.toString());
  Process.runSync('dart', ['format', file.path]);
  stdout.writeln('Wrote ${file.path}');
}

String _camel(String upperSnake) {
  final parts = upperSnake.toLowerCase().split('_').where((p) => p.isNotEmpty);
  final buf = StringBuffer();
  for (final (i, p) in parts.indexed) {
    buf.write(i == 0 ? p : '${p[0].toUpperCase()}${p.substring(1)}');
  }
  final name = buf.toString();
  // Dart identifiers cannot start with a digit.
  return RegExp(r'^\d').hasMatch(name) ? 'n$name' : name;
}
